import{_ as i,o as a,c as t,ag as o}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"0056 — Core compiles artifacts into an immutable Snapshot","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0056-core-compiles-artifacts-into-an-immutable-snapshot.md","filePath":"spec/decisions/0056-core-compiles-artifacts-into-an-immutable-snapshot.md"}'),r={name:"spec/decisions/0056-core-compiles-artifacts-into-an-immutable-snapshot.md"};function n(s,e,l,c,d,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="_0056-—-core-compiles-artifacts-into-an-immutable-snapshot" tabindex="-1">0056 — Core compiles artifacts into an immutable Snapshot <a class="header-anchor" href="#_0056-—-core-compiles-artifacts-into-an-immutable-snapshot" aria-label="Permalink to &quot;0056 — Core compiles artifacts into an immutable Snapshot&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-25</li><li>Scope: neutral Core, Form publisher, Provider and conformance dependency boundary</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The repository already validates data-only Form Packages and represents exact FormRefs, but current generation still begins in Go family catalogs. Aggregate generators, the official Provider, generated registries and parts of conformance import or enumerate the official families directly. A third-party package can be verified in isolation yet cannot join the same complete graph without source changes.</p><p>Moving those directories to separate repositories first would leave the same fixed roster behind an inter-repository build. Loading family callbacks or Go plugins would make publishers executable extensions and make Core portability depend on language/runtime identity. A generic Terraform resource carrying opaque JSON would avoid a roster only by giving up typed schema and state fidelity.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Introduce one artifact-first neutral compiler as specified in <a href="./../core/"><code>../core/</code></a>. The Core-owned verifier issues a non-forgeable package capability only after checking the complete data-only package closure. The compiler consumes those capabilities, exact Interface/Binding Definition artifacts and explicit default pins, then returns either one immutable Snapshot or stable diagnostics with no Snapshot.</p><p>Core imports no official family, Terraform Provider, Host, or conformance implementation. Official and external publishers enter through the same artifact interface. Exact identity is always <code>(group, kind, definitionVersion, schemaDigest)</code>; publisher and package provenance do not change FormRef equality. Same-Kind Forms in different groups coexist, and all resolution is group-first with no fallback.</p><p>Provider and conformance become downstream Adapters. The Provider additionally requires its own exact projection artifact and retains every historical state codec it promises. Family semantic corpora and executable Host behavior remain outside generic Core.</p><p>The compiler also owns the closed Host API lane ordering needed to enforce a Form&#39;s <code>requiresHostApi</code> lower bound and the generic recursive materialization of JSON Schema defaults into canonical effective desired bytes. Neither rule is a family or Provider extension point.</p><p>During the current one-repository stage the Go tracer is internal and carries no public SDK/module identity. Physical extraction and publication occur only after artifact parity and deletion gates close.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Zero installed families becomes a first-class valid Snapshot rather than a special test configuration.</li><li>Adding or removing a selected family changes artifact/default inputs, not Core source.</li><li>Dual old/new execution is temporary zero-diff evidence. It must end by deleting the fixed rosters and generators; it is not a compatibility layer.</li><li>Package acquisition remains an Adapter; complete byte/fixture/content closure verification belongs to Core&#39;s verifier. Signatures, publisher policy and revocation remain admission concerns. The compiler accepts only a verifier-issued capability and still enforces the caller&#39;s digest pin.</li><li>Terraform names, schemas, imports, state and diagnostics stay Provider-owned.</li><li>Provider 3.0.0 public/state/history behavior is locked before the Provider Adapter changes.</li><li>Specification 1.1 may record this compatible Core/API boundary independently from Forms, packages, Provider, Host adoption and literal Host API v1 graduation.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li>a built-in official-family registry;</li><li>family callbacks, Go plugins, WASM extensions, or package executable code;</li><li>Kind-only or latest-version resolution;</li><li>publisher identity inside FormRef equality;</li><li>a generic opaque primary Terraform resource;</li><li>repository extraction before dependency parity;</li><li>a permanent fallback to the old generator.</li></ul>',15)])])}const f=i(r,[["render",n]]);export{u as __pageData,f as default};
